        int a_col = t * TILE_SIZE + tx * 4;

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                int row_idx = a_row + i;
                int col_idx = a_col + j;
                if (row_idx < N && col_idx < N) {
                    tileA[ty * 4 + i][tx * 4 + j] = A[row_idx * N + col_idx];
                } else {
                    tileA[ty * 4 + i][tx * 4 + j] = 0.0f;
